#include <functional>
#include <iostream>

void f(int n1, int n2, int n3, const int& n4, int n5) {
    std::cout << n1 << ' ' << n2 << ' ' << n3 << ' ' << n4 << ' ' << n5 << '\n';
}

int g(int n) { return n * 2; }

struct Foo {
    void print_sum(int n1, int n2) { std::cout << n1 + n2 << '\n'; }
    int data = 10;
};

int main() {
    using namespace std::placeholders;

    // 1) Argument reordering and pass-by-reference
    int n = 7;
    auto f1 = std::bind(f, _2, 42, _1, std::cref(n), n);
    n = 10;
    f1(1, 2, 1001);  // Output: 2 42 1 10 7

    // 2) Nested bind shares placeholders
    auto f2 = std::bind(f, _3, std::bind(g, _3), _3, 4, 5);
    f2(10, 11, 12);  // Output: 12 24 12 4 5

    // 3) Bind to member function
    Foo foo;
    auto f3 = std::bind(&Foo::print_sum, &foo, 95, _1);
    f3(5);  // Output: 100

    // 4) Bind to data member
    auto f4 = std::bind(&Foo::data, _1);
    std::cout << f4(foo) << '\n';  // Output: 10
}

// Placeholder usage:
// _1, _2, _3... represent future arguments passed to the wrapper
//
// std::ref() and std::cref() pass arguments by reference
// Otherwise arguments are copied/moved into the wrapper

